#pragma once
// ---------------------------------------------------------------------------
// SBUS frame, laid out the way ExpressLRS does it (src/rx-serial/SerialSBUS.cpp):
// 0x0F + 16 x 11-bit channels (22 bytes, LSB first) + flags (bit3 failsafe,
// bit2 frame lost) + 0x00, every 9 ms, sent as inverted 100000 8E2.
// The line itself is generated by wave.h (the RA4M1 UART can't invert).
// ---------------------------------------------------------------------------
#include <Arduino.h>

#define SBUS_PERIOD_MS 9

// us -> SBUS raw, inverse of ArduPilot's AP_RCProtocol_SBUS scaling
// (us = raw * 1000/1600 + 875).
static inline uint16_t sbusRaw(uint16_t us) {
  int32_t r = (((int32_t)us - 875) * 16 + 5) / 10;   // rounded
  return (uint16_t)constrain(r, 0, 2047);
}

static void sbusFrame(uint8_t f[25], const uint16_t* us14, bool failsafe, bool lost) {
  memset(f, 0, 25);
  f[0] = 0x0F;
  for (int i = 0; i < 16; i++) {
    uint16_t raw = sbusRaw(i < 14 ? us14[i] : 1501);
    uint16_t bit = i * 11;
    for (int j = 0; j < 11; j++)
      if (raw & (1 << j)) f[1 + (bit + j) / 8] |= 1 << ((bit + j) % 8);
  }
  f[23] = (failsafe ? 0x08 : 0) | (lost ? 0x04 : 0);
  f[24] = 0x00;
}

